package skill

import (
	"embed"
	"io/fs"
	"path"
)

// skillsFS holds one directory per skill, each with a SKILL.md at its root.
//
//go:embed skills
var skillsFS embed.FS

// embeddedSkill is a skill carried by the binary.
type embeddedSkill struct {
	name        string
	description string
	files       fs.FS  // rooted at the skill's directory
	digest      string // digest of files, as recorded by an install
}

// embedded lists the skills carried by the binary, sorted by name.
var embedded = loadEmbedded()

func loadEmbedded() []*embeddedSkill {
	entries, err := fs.ReadDir(skillsFS, "skills")
	if err != nil {
		panic(err)
	}
	var skills []*embeddedSkill
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		sub, err := fs.Sub(skillsFS, path.Join("skills", e.Name()))
		if err != nil {
			panic(err)
		}
		data, err := fs.ReadFile(sub, skillFile)
		if err != nil {
			panic(err)
		}
		digest, err := digestFS(sub)
		if err != nil {
			panic(err)
		}
		meta, _ := parseMeta(data)
		skills = append(skills, &embeddedSkill{
			name:        e.Name(),
			description: meta["description"],
			files:       sub,
			digest:      digest,
		})
	}
	return skills
}

// lookupSkill returns the embedded skill with the given name, or nil.
func lookupSkill(name string) *embeddedSkill {
	for _, s := range embedded {
		if s.name == name {
			return s
		}
	}
	return nil
}

// summary shortens a description to the width the listings show.
func summary(desc string) string {
	const max = 100
	r := []rune(desc)
	if len(r) <= max {
		return desc
	}
	return string(r[:max-3]) + "..."
}

package skill

import (
	"bytes"
	"strings"
)

// Frontmatter keys an install adds to SKILL.md. They describe the install
// itself, so they are left out of the digest.
const (
	keyBy      = "x-embedded-by"
	keyVersion = "x-embedded-version"
	keyAt      = "x-embedded-at"
	keyDigest  = "x-embedded-digest"
)

var metaKeys = map[string]bool{keyBy: true, keyVersion: true, keyAt: true, keyDigest: true}

var bom = []byte("\xef\xbb\xbf")

// frontmatter locates the YAML frontmatter of a SKILL.md.
type frontmatter struct {
	prefix []byte   // a byte order mark, if the file starts with one
	lines  [][]byte // the lines after prefix, each with its line ending
	end    int      // index of the closing delimiter; lines[0] opens
}

// findFrontmatter reports the frontmatter of data, which must open on the
// first line and be closed by a later delimiter line.
func findFrontmatter(data []byte) (frontmatter, bool) {
	var prefix []byte
	if bytes.HasPrefix(data, bom) {
		prefix, data = data[:len(bom)], data[len(bom):]
	}
	lines := splitLines(data)
	if len(lines) == 0 || !isDelimiter(lines[0]) {
		return frontmatter{}, false
	}
	for i := 1; i < len(lines); i++ {
		if isDelimiter(lines[i]) {
			return frontmatter{prefix: prefix, lines: lines, end: i}, true
		}
	}
	return frontmatter{}, false
}

func splitLines(b []byte) [][]byte {
	var lines [][]byte
	for len(b) > 0 {
		i := bytes.IndexByte(b, '\n')
		if i < 0 {
			lines = append(lines, b)
			break
		}
		lines = append(lines, b[:i+1])
		b = b[i+1:]
	}
	return lines
}

func isDelimiter(line []byte) bool {
	return string(bytes.TrimRight(line, " \t\r\n")) == "---"
}

// field splits a frontmatter line into its key and value. An indented line
// continues the value above it and has no key of its own.
func field(line []byte) (key, value string, ok bool) {
	if len(line) == 0 || line[0] == ' ' || line[0] == '\t' {
		return "", "", false
	}
	k, v, found := strings.Cut(string(line), ":")
	if !found {
		return "", "", false
	}
	return strings.TrimSpace(k), unquote(strings.TrimSpace(v)), true
}

func unquote(s string) string {
	if len(s) >= 2 && (s[0] == '"' || s[0] == '\'') && s[len(s)-1] == s[0] {
		return s[1 : len(s)-1]
	}
	return s
}

// parseMeta returns the top-level keys of the frontmatter of data. A key
// given twice takes its last value.
func parseMeta(data []byte) (map[string]string, bool) {
	fm, ok := findFrontmatter(data)
	if !ok {
		return nil, false
	}
	meta := make(map[string]string)
	for _, line := range fm.lines[1:fm.end] {
		if k, v, ok := field(line); ok {
			meta[k] = v
		}
	}
	return meta, true
}

// normalize removes the install metadata from a SKILL.md, giving back the
// file as it was embedded. A frontmatter left with nothing in it is dropped.
func normalize(data []byte) []byte {
	fm, ok := findFrontmatter(data)
	if !ok {
		return data
	}
	var kept [][]byte
	empty := true
	for _, line := range fm.lines[1:fm.end] {
		if k, _, ok := field(line); ok && metaKeys[k] {
			continue
		}
		kept = append(kept, line)
		if len(bytes.TrimSpace(line)) > 0 {
			empty = false
		}
	}
	var b bytes.Buffer
	b.Write(fm.prefix)
	if !empty {
		b.Write(fm.lines[0])
		for _, line := range kept {
			b.Write(line)
		}
		b.Write(fm.lines[fm.end])
	}
	for _, line := range fm.lines[fm.end+1:] {
		b.Write(line)
	}
	return b.Bytes()
}

// render adds the install metadata to the end of the frontmatter of data,
// creating a frontmatter if there is none.
func render(data []byte, meta [][2]string) []byte {
	var m bytes.Buffer
	for _, kv := range meta {
		m.WriteString(kv[0] + ": " + kv[1] + "\n")
	}
	fm, ok := findFrontmatter(data)
	if !ok {
		var b bytes.Buffer
		b.WriteString("---\n")
		b.Write(m.Bytes())
		b.WriteString("---\n")
		b.Write(data)
		return b.Bytes()
	}
	var b bytes.Buffer
	b.Write(fm.prefix)
	for i, line := range fm.lines {
		if i == fm.end {
			b.Write(m.Bytes())
		}
		b.Write(line)
	}
	return b.Bytes()
}

package skill

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io/fs"
)

// skillFile is the file every skill directory has at its root.
const skillFile = "SKILL.md"

// junkFiles are written by file managers, not by people, so a skill
// directory holding them is still the one that was installed.
var junkFiles = map[string]bool{".DS_Store": true, "Thumbs.db": true, "desktop.ini": true}

// digestFS hashes the regular files of a skill directory in walk order. Each
// file contributes its slash-separated path, its length and its content,
// with SKILL.md taken without its install metadata. Anything other than a
// directory or a regular file makes the directory one the digest cannot
// describe.
func digestFS(fsys fs.FS) (string, error) {
	h := sha256.New()
	err := fs.WalkDir(fsys, ".", func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() || junkFiles[d.Name()] {
			return nil
		}
		if !d.Type().IsRegular() {
			return fmt.Errorf("%s: not a regular file", p)
		}
		data, err := fs.ReadFile(fsys, p)
		if err != nil {
			return err
		}
		if p == skillFile {
			data = normalize(data)
		}
		fmt.Fprintf(h, "%s\x00%d\x00", p, len(data))
		h.Write(data)
		return nil
	})
	if err != nil {
		return "", err
	}
	return "sha256:" + hex.EncodeToString(h.Sum(nil)), nil
}

package skill

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// agent is a coding agent whose skills directory the tool can write to.
type agent struct {
	name    string
	project string // skills directory, relative to the project root
	user    string // skills directory, relative to the home directory
}

// agents in the order the tool reports them.
var agents = []agent{
	{"github-copilot", ".agents/skills", ".copilot/skills"},
	{"claude-code", ".claude/skills", ".claude/skills"},
	{"cursor", ".agents/skills", ".cursor/skills"},
	{"codex", ".agents/skills", ".codex/skills"},
	{"gemini", ".agents/skills", ".gemini/skills"},
	{"antigravity", ".agents/skills", ".gemini/antigravity/skills"},
}

const (
	scopeProject = "project"
	scopeUser    = "user"
)

func lookupAgent(name string) (agent, bool) {
	for _, a := range agents {
		if a.name == name {
			return a, true
		}
	}
	return agent{}, false
}

// skillsDir returns where the agent keeps its skills in the given scope.
func (a agent) skillsDir(scope, root string) (string, error) {
	if scope == scopeProject {
		return filepath.Join(root, a.project), nil
	}
	if a.name == "claude-code" {
		if dir := strings.TrimSpace(os.Getenv("CLAUDE_CONFIG_DIR")); dir != "" {
			abs, err := filepath.Abs(dir)
			if err != nil {
				return "", err
			}
			return filepath.Join(abs, "skills"), nil
		}
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	home, err = filepath.Abs(home)
	if err != nil {
		return "", err
	}
	return filepath.Join(home, a.user), nil
}

// parseAgents splits the -agent values into names, checking each one.
func parseAgents(values []string) ([]string, error) {
	var names []string
	for _, v := range values {
		for _, name := range strings.Split(v, ",") {
			name = strings.TrimSpace(name)
			if name == "" {
				continue
			}
			if _, ok := lookupAgent(name); !ok && name != "all" && name != "detected" {
				known := make([]string, len(agents))
				for i, a := range agents {
					known[i] = a.name
				}
				sort.Strings(known)
				return nil, fmt.Errorf("skillembed: unknown agent %q (want one of %s, or all, or detected)",
					name, strings.Join(known, ", "))
			}
			names = append(names, name)
		}
	}
	return names, nil
}

// selectAgents expands all and detected. An agent is detected when the
// directory holding its skills directory exists; when detection is all that
// was asked for and it finds nothing, every agent is selected.
func selectAgents(names []string, scope, root string) ([]agent, error) {
	if len(names) == 0 {
		return nil, errors.New("skillembed: no agent selected")
	}
	var selected []agent
	seen := make(map[string]bool)
	add := func(a agent) {
		if !seen[a.name] {
			seen[a.name] = true
			selected = append(selected, a)
		}
	}
	for _, name := range names {
		switch name {
		case "all":
			for _, a := range agents {
				add(a)
			}
		case "detected":
			for _, a := range agents {
				dir, err := a.skillsDir(scope, root)
				if err != nil {
					return nil, err
				}
				if isDir(filepath.Dir(dir)) {
					add(a)
				}
			}
		default:
			a, _ := lookupAgent(name)
			add(a)
		}
	}
	if len(selected) == 0 {
		selected = append(selected, agents...)
	}
	return selected, nil
}

// targetDirs returns the distinct skills directories of the agents. In the
// project scope each must stay inside the project root once symbolic links
// are followed.
func targetDirs(selected []agent, scope, root string) ([]string, error) {
	var dirs []string
	seen := make(map[string]bool)
	for _, a := range selected {
		dir, err := a.skillsDir(scope, root)
		if err != nil {
			return nil, err
		}
		if !seen[dir] {
			seen[dir] = true
			dirs = append(dirs, dir)
		}
	}
	if scope == scopeProject {
		for _, dir := range dirs {
			if err := checkInside(root, dir); err != nil {
				return nil, err
			}
		}
	}
	return dirs, nil
}

// findProjectRoot walks up from the working directory to the nearest
// directory holding .git. Below that, the nearest directory already holding
// an agent's skills parent wins. Without a repository the working directory
// is the root. The home directory is refused, since the user scope is meant
// for it.
func findProjectRoot() (string, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", err
	}
	root, marked := cwd, ""
	for dir := cwd; ; dir = filepath.Dir(dir) {
		if marked == "" && (isDir(filepath.Join(dir, ".agents")) || isDir(filepath.Join(dir, ".claude"))) {
			marked = dir
		}
		if exists(filepath.Join(dir, ".git")) {
			root = dir
			if marked != "" {
				root = marked
			}
			break
		}
		if filepath.Dir(dir) == dir {
			break
		}
	}
	if home, err := os.UserHomeDir(); err == nil && sameDir(root, home) {
		return "", fmt.Errorf("skillembed: the search landed on the home directory (%s), "+
			"so pass --scope user to write there on purpose or --dir to name another directory", root)
	}
	return root, nil
}

func sameDir(a, b string) bool {
	ra, err := filepath.EvalSymlinks(a)
	if err != nil {
		return false
	}
	rb, err := filepath.EvalSymlinks(b)
	if err != nil {
		return false
	}
	return ra == rb
}

// checkInside fails when dir, with its symbolic links followed, lies outside
// root.
func checkInside(root, dir string) error {
	realRoot, err := filepath.EvalSymlinks(root)
	if err != nil {
		return err
	}
	realDir, err := resolve(dir)
	if err != nil {
		return err
	}
	if rel, err := filepath.Rel(realRoot, realDir); err != nil || rel == ".." || strings.HasPrefix(rel, "../") {
		return fmt.Errorf("skillembed: the destination is outside the project root (%s is really %s), "+
			"so pass --dir to write there on purpose", dir, realDir)
	}
	return nil
}

// resolve follows the symbolic links of an absolute path, including dangling
// ones, keeping whatever part of it does not exist yet.
func resolve(p string) (string, error) {
	real, err := filepath.EvalSymlinks(p)
	if err == nil {
		return real, nil
	}
	if !errors.Is(err, fs.ErrNotExist) {
		return "", err
	}
	if fi, lerr := os.Lstat(p); lerr == nil && fi.Mode()&fs.ModeSymlink != 0 {
		link, err := os.Readlink(p)
		if err != nil {
			return "", err
		}
		if !filepath.IsAbs(link) {
			link = filepath.Join(filepath.Dir(p), link)
		}
		return resolve(link)
	}
	parent := filepath.Dir(p)
	if parent == p {
		return p, nil
	}
	realParent, err := resolve(parent)
	if err != nil {
		return "", err
	}
	return filepath.Join(realParent, filepath.Base(p)), nil
}

func isDir(p string) bool {
	fi, err := os.Stat(p)
	return err == nil && fi.IsDir()
}

func exists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}

package skill

import (
	"errors"
	"io/fs"
	"os"
	"path/filepath"
)

// state is where a skill directory stands against the embedded skills.
type state int

const (
	stateMissing  state = iota // nothing there
	stateUpToDate              // installed by this tool, current, untouched
	stateOutdated              // installed by an older build of this tool, untouched
	stateModified              // installed by this tool, then edited
	stateForeign               // not installed by this tool
	stateOrphaned              // installed by this tool, which no longer carries it
)

func (s state) String() string {
	return [...]string{"missing", "up-to-date", "outdated", "modified", "foreign", "orphaned"}[s]
}

// inspect reports the state of the skill directory dir, given the digest of
// the embedded skill of that name ("" for none).
func inspect(dir, current string) (state, error) {
	fi, err := os.Stat(dir)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return stateMissing, nil
		}
		return 0, err
	}
	if !fi.IsDir() {
		return stateForeign, nil
	}
	data, err := os.ReadFile(filepath.Join(dir, skillFile))
	if err != nil {
		return stateForeign, nil
	}
	meta, ok := parseMeta(data)
	if !ok || meta[keyBy] != toolName || meta[keyDigest] == "" {
		return stateForeign, nil
	}
	actual, err := digestFS(os.DirFS(dir))
	if err != nil {
		return stateForeign, nil
	}
	switch recorded := meta[keyDigest]; {
	case actual != recorded:
		return stateModified, nil
	case recorded == current:
		return stateUpToDate, nil
	default:
		return stateOutdated, nil
	}
}

// Package skill implements "declscope skill": installing, removing and
// listing the agent skills embedded in the binary.
package skill

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"
	"text/tabwriter"
)

const (
	toolName = "declscope"
	// toolVersion is recorded in installed skills; builds without a
	// release version report devel.
	toolVersion = "devel"
)

// Main runs "declscope skill" with the arguments that follow "skill".
func Main(args []string) int {
	c := &cli{stdout: os.Stdout, stderr: os.Stderr}
	return c.run(args)
}

type cli struct {
	stdout, stderr io.Writer
}

func (c *cli) run(args []string) int {
	if len(args) == 0 {
		c.usage(c.stdout, "")
		return 0
	}
	switch cmd := args[0]; cmd {
	case "-h", "--help", "help":
		c.usage(c.stdout, "")
		return 0
	case "install", "uninstall", "list":
		return c.subcommand(cmd, args[1:])
	default:
		c.usage(c.stderr, "")
		return c.fail(fmt.Errorf("unknown skill subcommand %q", cmd))
	}
}

func (c *cli) fail(err error) int {
	fmt.Fprintf(c.stderr, "%s: %v\n", toolName, err)
	return 1
}

var synopses = map[string]string{
	"":          "Manage the agent skills embedded in declscope.",
	"install":   "Install the agent skills embedded in declscope, and remove the ones it no longer carries.",
	"uninstall": "Remove the agent skills embedded in declscope.",
	"list":      "Show the agent skills embedded in declscope, and where each one stands.",
}

// flagsUsage matches what flag.PrintDefaults prints for the flags below.
const flagsUsage = "Flags:\n" +
	"  -agent value\n" +
	"    \tTarget agent: {github-copilot|claude-code|cursor|codex|gemini|antigravity}, or all, or detected (repeatable) (default \"detected\")\n" +
	"  -dir string\n" +
	"    \tInstall to a custom directory (overrides -agent and -scope)\n" +
	"  -dry-run\n" +
	"    \tReport what would happen without writing\n" +
	"  -f\tOverwrite existing skills (shorthand)\n" +
	"  -force\n" +
	"    \tOverwrite existing skills\n" +
	"  -scope value\n" +
	"    \tInstallation scope: {project|user} (default project)\n"

// usage prints the help of a subcommand, or of "skill" itself for "".
func (c *cli) usage(w io.Writer, cmd string) {
	fmt.Fprintf(w, "%s\n\nUsage:\n", synopses[cmd])
	if cmd == "" {
		fmt.Fprint(w, "  declscope skill install   [flags] [skill...]\n"+
			"  declscope skill uninstall [flags] [skill...]\n"+
			"  declscope skill list      [flags] [skill...]\n")
	} else {
		fmt.Fprintf(w, "  declscope skill %s [flags] [skill...]\n", cmd)
	}
	fmt.Fprintf(w, "\n%s\nEmbedded skills:\n", flagsUsage)
	tw := tabwriter.NewWriter(w, 0, 8, 2, ' ', 0)
	for _, s := range embedded {
		fmt.Fprintf(tw, "  %s\t%s\n", s.name, summary(s.description))
	}
	tw.Flush()
}

// options are the flags and arguments shared by the subcommands.
type options struct {
	agents []string // -agent values, each a comma-separated list
	scope  string
	dir    string
	dryRun bool
	force  bool
	skills []string
}

// agentsFlag collects repeated -agent values. The first one given replaces
// the default.
type agentsFlag struct {
	values []string
	set    bool
}

func (f *agentsFlag) String() string { return strings.Join(f.values, ",") }

func (f *agentsFlag) Set(v string) error {
	if !f.set {
		f.values, f.set = nil, true
	}
	f.values = append(f.values, v)
	return nil
}

type scopeFlag struct{ value string }

func (f *scopeFlag) String() string { return f.value }

func (f *scopeFlag) Set(v string) error {
	if v == "" {
		return errors.New("scope must not be empty")
	}
	f.value = v
	return nil
}

func parseFlags(args []string) (options, error) {
	var o options
	agentList := &agentsFlag{values: []string{"detected"}}
	scope := &scopeFlag{value: scopeProject}
	fs := flag.NewFlagSet("skill", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Usage = func() {}
	fs.Var(agentList, "agent", "Target agent")
	fs.StringVar(&o.dir, "dir", "", "Install to a custom directory (overrides -agent and -scope)")
	fs.BoolVar(&o.dryRun, "dry-run", false, "Report what would happen without writing")
	fs.BoolVar(&o.force, "f", false, "Overwrite existing skills (shorthand)")
	fs.BoolVar(&o.force, "force", false, "Overwrite existing skills")
	fs.Var(scope, "scope", "Installation scope: {project|user}")
	if err := fs.Parse(args); err != nil {
		return o, err
	}
	o.agents, o.scope, o.skills = agentList.values, scope.value, fs.Args()
	return o, nil
}

func (c *cli) subcommand(cmd string, args []string) int {
	o, err := parseFlags(args)
	if errors.Is(err, flag.ErrHelp) {
		c.usage(c.stdout, cmd)
		return 0
	}
	if err != nil {
		c.usage(c.stderr, cmd)
		return c.fail(err)
	}
	p, err := makePlan(o)
	if err != nil {
		return c.fail(err)
	}
	switch cmd {
	case "install":
		return c.install(p, o)
	case "uninstall":
		return c.uninstall(p, o)
	default:
		return c.list(p)
	}
}

// header names the project root, when the targets were found from it.
func (c *cli) header(p *plan) {
	if p.root != "" {
		fmt.Fprintf(c.stdout, "Project root: %s\n\n", p.root)
	}
}

func (c *cli) list(p *plan) int {
	c.header(p)
	seen := make(map[string]bool)
	for _, s := range p.skills {
		if !seen[s.name] {
			seen[s.name] = true
			fmt.Fprintf(c.stdout, "%s\n  %s\n", s.name, summary(s.description))
		}
	}
	fmt.Fprintln(c.stdout)
	tw := tabwriter.NewWriter(c.stdout, 0, 8, 2, ' ', 0)
	fmt.Fprintln(tw, "SKILL\tSTATE\tPATH")
	for _, it := range p.items {
		fmt.Fprintf(tw, "%s\t%s\t%s\n", it.name, it.state, it.path)
	}
	tw.Flush()
	return 0
}

// result is one line of what install or uninstall did.
type result struct {
	verb, name, path, note string
}

// report prints the results, which stop short of the action that failed.
func (c *cli) report(p *plan, dryRun bool, results []result) {
	if len(results) == 0 {
		return
	}
	c.header(p)
	tw := tabwriter.NewWriter(c.stdout, 0, 8, 2, ' ', 0)
	for _, r := range results {
		verb := r.verb
		if dryRun {
			verb = "would be " + verb
		}
		line := verb + "\t" + r.name + "\t" + r.path
		if r.note != "" {
			line += " (" + r.note + ")"
		}
		fmt.Fprintln(tw, line)
	}
	tw.Flush()
}

const (
	noteEdited  = "edited after installing; use --force"
	noteForeign = "installed by something else; use --force"
)

package skill

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

// plan is what a subcommand works on: the skills directories it targets and
// the state of every skill in them, taken before anything is changed.
type plan struct {
	root   string // project root; "" when the targets were not found from one
	dirs   []string
	skills []*embeddedSkill // as named on the command line, repeats included
	items  []item
}

// item is one skill directory in a target.
type item struct {
	name  string
	dir   string // the skills directory holding it
	path  string
	state state
	skill *embeddedSkill // nil for an orphan
}

func makePlan(o options) (*plan, error) {
	if o.scope != scopeProject && o.scope != scopeUser {
		return nil, fmt.Errorf("skillembed: unknown scope %q (want project or user)", o.scope)
	}
	p := new(plan)
	if o.dir == "" && o.scope == scopeProject {
		root, err := findProjectRoot()
		if err != nil {
			return nil, err
		}
		p.root = root
	}
	names, err := parseAgents(o.agents)
	if err != nil {
		return nil, err
	}
	if o.dir != "" {
		dir, err := filepath.Abs(o.dir)
		if err != nil {
			return nil, err
		}
		p.dirs = []string{dir}
	} else {
		selected, err := selectAgents(names, o.scope, p.root)
		if err != nil {
			return nil, err
		}
		if p.dirs, err = targetDirs(selected, o.scope, p.root); err != nil {
			return nil, err
		}
	}

	entries := make([][]fs.DirEntry, len(p.dirs))
	for i, dir := range p.dirs {
		es, err := os.ReadDir(dir)
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		}
		entries[i] = es
	}

	if p.skills, err = selectSkills(o.skills); err != nil {
		return nil, err
	}
	for i, dir := range p.dirs {
		for _, s := range p.skills {
			path := filepath.Join(dir, s.name)
			st, err := inspect(path, s.digest)
			if err != nil {
				return nil, err
			}
			p.items = append(p.items, item{name: s.name, dir: dir, path: path, state: st, skill: s})
		}
		if len(o.skills) > 0 {
			continue // orphans are only looked for when every skill is in play
		}
		for _, e := range entries[i] {
			name := e.Name()
			if !e.IsDir() || strings.HasPrefix(name, ".") || lookupSkill(name) != nil {
				continue
			}
			path := filepath.Join(dir, name)
			st, err := inspect(path, "")
			if err != nil {
				return nil, err
			}
			// Installed by this tool and untouched since: with no embedded
			// skill to compare against, that reads as outdated.
			if st == stateOutdated {
				p.items = append(p.items, item{name: name, dir: dir, path: path, state: stateOrphaned})
			}
		}
	}
	return p, nil
}

// selectSkills returns the embedded skills named, or all of them.
func selectSkills(names []string) ([]*embeddedSkill, error) {
	if len(names) == 0 {
		return embedded, nil
	}
	var skills []*embeddedSkill
	for _, name := range names {
		s := lookupSkill(name)
		if s == nil {
			known := make([]string, len(embedded))
			for i, s := range embedded {
				known[i] = s.name
			}
			return nil, fmt.Errorf("skillembed: unknown skill %q (embedded: %s)", name, strings.Join(known, ", "))
		}
		skills = append(skills, s)
	}
	return skills, nil
}

func (c *cli) install(p *plan, o options) int {
	installedAt := time.Now().UTC().Format(time.RFC3339)
	var (
		results []result
		refused []item
		err     error
	)
	for _, it := range p.items {
		r := result{name: it.name, path: it.path}
		switch {
		case it.state == stateOrphaned:
			r.verb, r.note = "removed", "no longer embedded in "+toolName
			if !o.dryRun {
				if rerr := os.RemoveAll(it.path); rerr != nil {
					err = fmt.Errorf("remove %s from %s: %w", it.name, it.dir, rerr)
				}
			}
		case it.state == stateUpToDate && !o.force:
			r.verb, r.note = "skipped", "already up to date"
		case it.state == stateModified && !o.force:
			r.verb, r.note = "skipped", noteEdited
			refused = append(refused, it)
		case it.state == stateForeign && !o.force:
			r.verb, r.note = "skipped", noteForeign
			refused = append(refused, it)
		default:
			r.verb = "updated"
			if it.state == stateMissing {
				r.verb = "installed"
			}
			if !o.dryRun {
				if ierr := installSkill(it, installedAt); ierr != nil {
					err = fmt.Errorf("install %s into %s: %w", it.name, it.dir, ierr)
				}
			}
		}
		if err != nil {
			break
		}
		results = append(results, r)
	}
	c.report(p, o.dryRun, results)
	if err != nil {
		return c.fail(err)
	}
	if len(refused) > 0 {
		var b strings.Builder
		b.WriteString("refusing to overwrite skills this tool did not install, or that were edited after installing:\n")
		for _, it := range refused {
			fmt.Fprintf(&b, "  %s (%s)\n", it.path, it.state)
		}
		b.WriteString("re-run with --force to overwrite")
		return c.fail(errors.New(b.String()))
	}
	return 0
}

func (c *cli) uninstall(p *plan, o options) int {
	var (
		results []result
		err     error
	)
	for _, it := range p.items {
		r := result{name: it.name, path: it.path}
		switch {
		case it.state == stateMissing:
			r.verb, r.note = "skipped", "not installed"
		case it.state == stateModified && !o.force:
			r.verb, r.note = "skipped", noteEdited
		case it.state == stateForeign && !o.force:
			r.verb, r.note = "skipped", noteForeign
		default:
			r.verb = "removed"
			if !o.dryRun {
				err = os.RemoveAll(it.path)
			}
		}
		if err != nil {
			break
		}
		results = append(results, r)
	}
	c.report(p, o.dryRun, results)
	if err != nil {
		return c.fail(err)
	}
	return 0
}

// installSkill writes the skill into a temporary directory beside its
// destination, then swaps it into place, so a reader never sees half of it.
func installSkill(it item, installedAt string) error {
	if err := os.MkdirAll(it.dir, 0o755); err != nil {
		return err
	}
	tmp, err := os.MkdirTemp(it.dir, "."+it.name+".tmp-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmp) // gone already once renamed into place

	meta := [][2]string{
		{keyBy, toolName},
		{keyVersion, toolVersion},
		{keyAt, strconv.Quote(installedAt)},
		{keyDigest, strconv.Quote(it.skill.digest)},
	}
	if err := writeFiles(it.skill.files, tmp, meta); err != nil {
		return err
	}

	// Reserve a name to move the previous install aside to.
	old, err := os.MkdirTemp(it.dir, "."+it.name+".old-*")
	if err != nil {
		return err
	}
	if err := os.Remove(old); err != nil {
		return err
	}
	if err := os.Rename(it.path, old); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	if err := os.Rename(tmp, it.path); err != nil {
		os.Rename(old, it.path) // put the previous install back
		return err
	}
	os.RemoveAll(old) // best effort: the new install is in place
	return nil
}

// writeFiles copies a skill into dir, adding the install metadata to its
// SKILL.md.
func writeFiles(files fs.FS, dir string, meta [][2]string) error {
	return fs.WalkDir(files, ".", func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		target := filepath.Join(dir, filepath.FromSlash(p))
		if d.IsDir() {
			return os.MkdirAll(target, 0o755)
		}
		data, err := fs.ReadFile(files, p)
		if err != nil {
			return err
		}
		if p == skillFile {
			data = render(data, meta)
		}
		return os.WriteFile(target, data, 0o644)
	})
}

